def solve(data):
    text = data['text']
    rows = []
    row = []
    field = ''
    mode = 'start'
    ended = False
    for char in text:
        ended = False
        if mode == 'cr':
            if char != '\n':
                raise ValueError('bare_cr')
            mode = 'start'
            ended = True
        elif mode == 'quoted':
            if char == '"':
                mode = 'closed'
            else:
                field = field + char
        elif mode == 'closed':
            if char == '"':
                field = field
                mode = 'quoted'
            elif char == ';':
                row.append(field)
                field = ''
                mode = 'start'
            elif char in ('\n', '\r'):
                row.append(field)
                rows.append(row)
                row = []
                field = ''
                mode = 'cr' if char == '\r' else 'start'
                ended = True
            else:
                raise ValueError('after_quote')
        else:
            if char == '"':
                if mode != 'start':
                    raise ValueError('quote_in_plain')
                mode = 'quoted'
            elif char == ';':
                row.append(field)
                field = ''
                mode = 'start'
            elif char in ('\n', '\r'):
                row.append(field)
                rows.append(row)
                row = []
                field = ''
                mode = 'cr' if char == '\r' else 'start'
                ended = True
            else:
                field = field + char
                mode = 'plain'
    if mode in ('quoted', 'cr'):
        raise ValueError('incomplete_record')
    if text and not ended:
        row.append(field)
        rows.append(row)
    return rows

